# owner: platform
"""Find the stretches of opening hours nobody is covering."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans
from hourglass.errors import OutsideHoursError


def _check_inside(worked, opening):
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise OutsideHoursError(
                f"{format_span(span)} is outside "
                f"{format_span(opening)}"
            )


def _edges(worked, opening):
    points = [opening.start]
    for span in merge_spans(worked):
        points += [span.start, span.end]
    points.append(opening.end)
    return points


def _uncovered(worked, opening):
    edges = _edges(worked, opening)
    pairs = zip(edges[::2], edges[1::2])
    return [
        Span(left, right)
        for left, right in pairs
        if left < right
    ]


def _label(span):
    return f"gap {format_span(span)} ({span.minutes} min)"


# ---
def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label per uncovered stretch, such as
    gap 12:00-13:00 (60 min). Raises OutsideHoursError when a
    worked span is not inside opening hours."""
    worked = list(worked)
    _check_inside(worked, opening)
    return [_label(gap) for gap in _uncovered(worked, opening)]
EOF
cat > tests/test_gaps.py <<'EOF'
# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps
from hourglass.errors import OutsideHoursError, ProjectError


def spans(*texts):
    return [parse_span(text) for text in texts]


OPEN = parse_span("09:00-17:00")


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        worked = spans("10:00-16:30")
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 16:30-17:00 (30 min)"]
        )

    def test_nobody_worked(self):
        self.assertEqual(
            find_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        worked = spans("09:00-13:00", "12:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_touching_spans_leave_no_gap(self):
        worked = spans("09:00-12:00", "12:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_unsorted_input(self):
        worked = spans("14:00-17:00", "09:00-11:00")
        self.assertEqual(
            find_gaps(worked, OPEN), ["gap 11:00-14:00 (180 min)"]
        )

    def test_starting_early_raises(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps(spans("08:00-12:00"), OPEN)

    def test_ending_late_raises(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps(spans("12:00-18:00"), OPEN)

    def test_error_is_a_project_error(self):
        with self.assertRaises(ProjectError):
            find_gaps(spans("08:00-12:00"), OPEN)
EOF
